const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
/* Vorladen erst, wenn das Kind im Spiel ist (Startseite bleibt leicht) */
const onSpiel = (f, d = 1500) => { if (document.body.dataset.screen === 'spiel') return setTimeout(f, d); addEventListener('gsm-spiel', () => setTimeout(f, d), { once: true }); };
/* Gemalte 3D-Icons statt flacher Symbole (im SVG-Rahmen, damit alle Größen und Animationen gleich bleiben) */
const PIC = { check: 'check', lock: 'lock', star: 'star', snd: 'snd', x: 'x', flame: 'flame', coin: 'coin', cup: 'trophy', trophy: 'trophy', gem: 'gem', heart: 'heart', gift: 'gift', bolt: 'bolt', chest: 'chest', unlock: 'unlock' };
