  const c = +el.dataset.c, f = (n) => { im.src = `/grundschulmax/sp/bal/p${n}.webp`; im.style.filter = n < 3 ? `hue-rotate(${BALHUE[c]}deg)` : ''; };
  el.classList.add('popd2'); if (b) b.style.opacity = 0;
