      b.el.style.transform = `translate(${b.x + Math.sin(ts / 600 + b.ph) * 10}px,${b.y}px) rotate(${Math.sin(ts / 700 + b.ph) * 6}deg)`;
      if (b.y < -130) { b.el.remove(); return false; }
