    const fh = frog.offsetHeight, x = pr.left - gr.left + pr.width / 2 - fw / 2, y = pr.top - gr.top + pr.width * .22 - fh * .92;
    if (!anim) { frog.style.transform = `translate(${x}px,${y}px)`; frog._x = x; frog._y = y; return Promise.resolve(); }
    const x0 = frog._x, y0 = frog._y, h = 70 + Math.abs(i - at) * 6;
