/* ===================== DEUTSCH ===================== */
WHO = 'max';
const ZUG = [
  [{ w: ['Ba', 'na', 'ne'], x: 'Bo', a: 'banane' }, { w: ['To', 'ma', 'te'], x: 'Mo', a: 'tomate' }, { w: ['Ra', 'ke', 'te'], x: 'Ku', a: 'rakete' }],
  [{ w: ['Erd', 'bee', 're'], x: 'Ber', a: 'erdbeere' }, { w: ['Ka', 'rot', 'te'], x: 'Ko', a: 'karotte' }, { w: ['Schmet', 'ter', 'ling'], x: 'Lang', a: 'schmetterling' }],
  [{ w: ['Die', 'Katze', 'schläft', 'gern.'], x: 'laut', a: 'cat' }, { w: ['Der', 'Fisch', 'schwimmt', 'schnell.'], x: 'fliegt', a: 'fish' }, { w: ['Die', 'Sonne', 'scheint', 'hell.'], x: 'Regen', a: 'sun' }],
  [{ w: ['Der', 'Fuchs', 'schleicht', 'durch', 'den', 'Wald.'], x: 'Wasser', a: 'fuchs' }, { w: ['Die', 'Eule', 'jagt', 'in', 'der', 'Nacht.'], x: 'Mittag', a: 'eule' }, { w: ['Die', 'Rakete', 'fliegt', 'zum', 'Mond.'], x: 'Hund', a: 'rakete' }],
];
ZUG.forEach((L, g) => L.forEach((W) => { const full = g < 2 ? W.w.join('').replace(/^(.)(.*)$/, (m, a, b) => a + b.toLowerCase()) : W.w.join(' '); W.full = full; W.k = vk(g < 2 ? full + '! Super gelesen!' : full + ' Super gelesen!'); W.slow = g < 2 ? vk(W.w.join(' – ')) : null; }));
const ZUGI = [vk('Schau dir das Bild an und tipp die Silben in der richtigen Reihenfolge.'), vk('Lange Wörter! Tipp die Silben der Reihe nach.'), vk('Jetzt bauen wir Sätze! Welches Wort kommt zuerst?'), vk('Lange Sätze! Bring die Wörter in die richtige Reihenfolge.')];
const vkZugNo = vk('Hör genau hin. Was kommt als Nächstes?'), vkZugSNo = vk('Lies den Satz nochmal. Welches Wort passt als Nächstes?');
function gZug(T) {
  gs.className = 'gs g-zug g-zug2';
  const WORDS = ZUG[G()], sent = G() >= 2;
  let wi = 0, idx = 0, busy = false;
  const ZS = (n) => `/grundschulmax/sp/zug/${n}.webp`;
  gs.innerHTML = `${SKY('zug', [['k2', 6, 2, 30, 300], ['k1', 60, 4, 36, 260], ['k0', 30, 12, 26, 150], ['k1', 82, 15, 44, 170], ['k0', 45, 22, 40, 110]], [], 1672)}<div class="pic" id="pic"></div><div class="schips${sent ? ' sent' : ''}" id="ch"></div><div class="rail"><div class="train" id="tr"></div></div>`;
  const tr = $('#tr'), rail = $('.rail', gs);
  function placeRail() { const sk = $('.gsky', gs); if (!sk) return; const W = sk.clientWidth, H = sk.clientHeight, sc = Math.max(W / 1672, H / 941), oy = (H - 941 * sc) * .7, ry = oy + 668 * sc, gsTop = sk.offsetTop; rail.style.bottom = Math.max(8, gs.clientHeight - (ry + gsTop)) + 'px'; }
  const roR = new ResizeObserver(placeRail); roR.observe(gs); requestAnimationFrame(placeRail);
  function fit() { tr.style.setProperty('--sc', 1); const w = tr.scrollWidth, W = gs.clientWidth - 16; tr.style.setProperty('--sc', Math.min(1, W / w)); }
  function build() {
    const W = WORDS[wi]; idx = 0; busy = false;
    $('#pic').innerHTML = ART[W.a];
    tr.innerHTML = W.w.map((_, i) => `<div class="wag wag2${sent ? ' wide' : ''}"><img src="${ZS('w' + (i % 3))}" alt="" draggable="false"><div class="slot"></div></div>`).join('') + `<div class="loco loco2"><img src="${ZS('loco')}" alt="" draggable="false"></div>`;
    $('#ch').innerHTML = shuf([...W.w, W.x]).map((s) => `<button class="sy" data-s="${s}">${s}</button>`).join('');
    $$('#ch .sy').forEach((b) => (b.onclick = () => tap(b)));
    fit();
  }
  function arrive() { tr.classList.add('in'); reflow(tr); tr.classList.remove('in'); tr.classList.add('arr'); sfx.chug(); setTimeout(() => tr.classList.remove('arr'), 1500); }
  function smoke() {
    const lr = $('.loco', tr).getBoundingClientRect(), gr = gs.getBoundingClientRect();
    for (let i = 0; i < 7; i++) setTimeout(() => { if (!alive(T)) return; const s = document.createElement('img'); s.src = ZS('k0'); s.className = 'smk2'; s.style.left = lr.left - gr.left + lr.width * .68 + 'px'; s.style.top = lr.top - gr.top - 10 + 'px'; gs.appendChild(s); setTimeout(() => s.remove(), 1600); }, i * 150);
  }
  function tap(b) {
    if (busy) return;
    const W = WORDS[wi], s = b.dataset.s;
    if (s === W.w[idx]) {
      const slot = $$('.slot', tr)[idx], a = b.getBoundingClientRect(), z = slot.getBoundingClientRect();
      const ghost = b.cloneNode(true); ghost.style.cssText = `position:fixed;left:${a.left}px;top:${a.top}px;width:${a.width}px;height:${a.height}px;margin:0;z-index:60;animation:none`; document.body.appendChild(ghost);
      b.classList.add('used'); sfx.ok();
      ghost.animate([{ transform: 'none' }, { transform: `translate(${(z.left - a.left) * .5}px,${(z.top - a.top) * .5 - 50}px) scale(1.1) rotate(-6deg)`, offset: .5 }, { transform: `translate(${z.left - a.left + (z.width - a.width) / 2}px,${z.top - a.top + (z.height - a.height) / 2}px) scale(.8)` }], { duration: 520, easing: 'cubic-bezier(.4,0,.2,1)' })
        .onfinish = () => { ghost.remove(); slot.textContent = s; slot.classList.add('full'); };
      idx++;
      if (idx === W.w.length) {
        busy = true; right(true);
        setTimeout(() => {
          if (!alive(T)) return;
          say(VL.get(W.k).t, 'happy', W.k); fb(true, 'Super gelesen!', W.full);
          setTimeout(() => { if (!alive(T)) return; smoke(); sfx.chug(); tr.classList.add('go'); }, 900);
          setTimeout(() => {
            if (!alive(T)) return;
            tr.classList.remove('go'); wi++;
            if (wi < WORDS.length) { build(); arrive(); }
            else finish('Alle Züge sind abgefahren!', ['Silben hören und ordnen ist die Basis fürs Lesen.', 'Lange Wörter in Silben zerlegen hilft beim Lesen und Schreiben.', 'Wer Sätze bauen kann, versteht, wie Sprache funktioniert.', 'Lange Sätze richtig ordnen: perfekt für Aufsätze.'][G()]);
          }, 2600);
        }, 520);
      } else { dmax.className = 'dmax happy'; sayEl.textContent = 'Genau! Und weiter?'; }
    } else {
      wrong(); restart(b, 'shk'); sfx.no();
      if (sent) { say('Lies den Satz nochmal. Welches Wort passt als Nächstes?', 'think', vkZugSNo); fb(false, 'Fast!', idx === 0 ? 'Welches Wort steht ganz am Anfang? Lies den Satz leise mit.' : `Bis jetzt: „${W.w.slice(0, idx).join(' ')} …“`, { ms: 2200 }); }
      else { say(`Hör genau hin: ${W.w.join(' – ')}.`, 'think', W.slow); fb(false, 'Fast!', `Sprich langsam: ${W.w.join(' – ')}`, { ms: 2200 }); }
    }
  }
  build();
  progress(WORDS.length * 1);
  sayK(ZUGI[G()]);
  startOverlay('Silben-Zug starten', sent ? '3 Sätze · Wörter in die richtige Reihenfolge' : '3 Wörter · Silben der Reihe nach', () => { arrive(); });
  const ro = new ResizeObserver(fit); ro.observe(gs);
  return () => { ro.disconnect(); roR.disconnect(); };
}

