    xT.font = `400 ${fs}px ${fam()}`; const w = xT.measureText(L.items[i]).width, x0 = (W - w) / 2;
    sayK(vkStiftShow);
    cov.style.left = x0 - lw + 'px'; cov.style.width = w + lw * 2 + 'px';
    const an = cov.animate([{ clipPath: 'inset(0 0 0 0)' }, { clipPath: 'inset(0 0 0 100%)' }], { duration: 1800, easing: 'ease-in-out', fill: 'none' }); an.onfinish = an.oncancel = () => { cov.style.removeProperty('width'); cov.style.removeProperty('left'); };
    pen.style.top = base - fs * .5 + 'px';
