      const st2 = document.createElement('img'); st2.src = SS('star'); st2.className = 'bigstar'; st2.style.left = r.left - gr.left + r.width / 2 + 'px'; st2.style.top = r.top - gr.top + r.height / 2 + 'px'; gs.appendChild(st2); setTimeout(() => st2.remove(), 1400);
      i++; setTimeout(() => { if (!alive(T)) return; if (i < L.items.length) render(); else finish('Toll geschrieben!', `${L.what}: Max zeigt die richtige Richtung und lobt jede schöne Spur.`); }, 1300);
