/* ===================== ENGLISCH ===================== */
WHO = 'emma';
const SW = (c) => `<span class="sw" style="background:${c}"></span>`;
const MEM = [
  { intro: vk('Memory auf Englisch! Finde zu jedem Wort das passende Bild.'), P: [['cat', 'cat'], ['sun', 'sun'], ['apple', 'apple'], ['fish', 'fish']].map(([w, a]) => ({ k: w, a: { t: 'w', v: w }, b: { t: 'p', v: a } })) },
  { intro: vk('Farben und Zahlen auf Englisch! Finde die Paare.'), P: [['red', SW('#e8473c')], ['blue', SW('#2f6fe0')], ['green', SW('#2fae5c')], ['three', '<b class="dig">3</b>'], ['five', '<b class="dig">5</b>'], ['ten', '<b class="dig">10</b>']].map(([w, h]) => ({ k: w, a: { t: 'w', v: w }, b: { t: 'h', v: h } })) },
  { intro: vk('Längere Wörter! Welches englische Wort gehört zu welchem Bild?'), P: [['rocket', 'rakete'], ['strawberry', 'erdbeere'], ['butterfly', 'schmetterling'], ['carrot', 'karotte'], ['owl', 'eule'], ['banana', 'banane']].map(([w, a]) => ({ k: w, a: { t: 'w', v: w }, b: { t: 'p', v: a } })) },
  { intro: vk('Frage und Antwort! Welche Antwort passt zu welcher Frage?'), P: [["What's your name?", 'My name is Lea.'], ['How old are you?', "I'm nine."], ['Where do you live?', 'I live in Hamburg.'], ['Have you got a pet?', 'Yes, a cat.'], ['Can you swim?', 'Yes, I can.'], ["What's your favourite colour?", "It's blue."]].map(([q, a]) => ({ k: q, a: { t: 'w', v: q }, b: { t: 'w', v: a } })) },
];
MEM.forEach((L) => L.P.forEach((p) => { [p.a, p.b].forEach((c) => { if (c.t === 'w') c.key = vk(c.v, 'en'); }); }));
const vkMemNo = vk('Fast! Gleich nochmal versuchen.');
function gMem(T) {
  gs.className = 'gs g-mem g-mem2';
  const L = MEM[G()], n = L.P.length;
  const cards = shuf(L.P.flatMap((p) => [{ p, c: p.a }, { p, c: p.b }]));
  const long = G() === 3;
  gs.innerHTML = `${SKY('mem', [], [])}<i class="msun"></i><i class="mdust"></i><div class="mgrid n${n * 2}${long ? ' long' : ''}">${cards.map(({ c }, i) => `<div class="mc" data-i="${i}"><div class="in"><div class="fa"><img class="mbk" src="/grundschulmax/sp/mem/back.webp" alt="" draggable="false"></div><div class="ba t-${c.t}">${c.t === 'p' ? ART[c.v] : c.t === 'h' ? c.v : `<span>${c.v}</span>`}</div></div></div>`).join('')}</div>`;
  const fit = () => $$('.mc .ba > span:not(.sw)', gs).forEach((sp) => { const box = sp.parentElement; if (box.clientWidth < 30 || box.clientHeight < 30) return; let f = parseFloat(getComputedStyle(box).width) * .22; sp.style.whiteSpace = /\s/.test(sp.textContent.trim()) ? 'normal' : 'nowrap'; sp.style.fontSize = f + 'px'; let k = 0; const nw = sp.style.whiteSpace === 'nowrap'; sp.style.width = nw ? 'max-content' : '86%'; sp.style.justifySelf = 'center'; while (((nw ? sp.offsetWidth > box.clientWidth * .64 : sp.scrollWidth > sp.clientWidth + 1) || sp.offsetHeight > box.clientHeight * (nw ? .6 : .8)) && k++ < 40) { f *= .92; sp.style.fontSize = f + 'px'; } });
  requestAnimationFrame(fit); setTimeout(fit, 400); setTimeout(fit, 1500); const roM = new ResizeObserver(fit); roM.observe(gs); $$('.mc', gs).forEach((m) => roM.observe(m));
  let open = [], found = 0, lock = false;
  $$('.mc', gs).forEach((el) => (el.onclick = () => {
    if (lock || el.classList.contains('up')) return;
    const { p, c } = cards[+el.dataset.i]; el.classList.add('up'); sfx.flip();
    if (c.key) voice(c.key);
    open.push([el, p]);
    if (open.length === 2) {
      lock = true;
      const [[e1, p1], [e2, p2]] = open;
      if (p1 === p2) {
        setTimeout(() => {
          if (!alive(T)) return;
          e1.classList.add('ok'); e2.classList.add('ok'); sfx.ok(); found++;
          const s3 = right(); if (s3) sayK(P.streak, 'happy'); else { dmax.className = 'dmax happy'; sayEl.textContent = 'Ein Paar!'; }
          fb(true, 'Ein Paar!', G() === 2 ? `${p1.a.v} heißt ${p1.b.v[0].toUpperCase() + p1.b.v.slice(1)}.` : G() === 3 ? `${p1.a.v} – ${p1.b.v}` : `${p1.k}`, { ms: 1300 });
          open = []; lock = false;
          if (found === n) setTimeout(() => { if (!alive(T)) return; finish('Alle Paare gefunden!', ['Hören, sehen, merken: So bleiben englische Wörter hängen.', 'Farben und Zahlen auf Englisch sitzen.', 'Englisch und Deutsch verbinden: so wächst der Wortschatz.', 'Fragen und Antworten: Dein Kind kann sich auf Englisch unterhalten.'][G()]); }, 800);
        }, 420);
      } else {
        wrong(); sayK(vkMemNo, 'think');
        setTimeout(() => { if (!alive(T)) return; e1.classList.remove('up'); e2.classList.remove('up'); open = []; lock = false; }, 1100);
      }
    }
  }));
  progress(n);
  // Fehler beim Memory zählen weniger: Merken gehört dazu
  const W = wrong; wrong = () => { st.streak = 0; st.errs += .34; drawProg(); };
  sayK(L.intro);
  return () => { wrong = W; roM.disconnect(); };
}

/* Buchstaben-Blasen: englische Wörter buchstabieren */
const BLASEN = [
  { intro: vk('Buchstaben-Blasen! Hör das Wort und tipp die Buchstaben der Reihe nach.'), W: [{ w: 'cat', a: 'cat' }, { w: 'sun', a: 'sun' }, { w: 'fish', a: 'fish' }] },
  { intro: vk('Längere Wörter! Buchstabiere das Wort auf Englisch.'), W: [{ w: 'apple', a: 'apple' }, { w: 'frog', a: 'frosch' }, { w: 'tomato', a: 'tomate' }] },
  { intro: vk('Jetzt ohne Bild! Wie heißt das Wort auf Englisch?'), W: [{ w: 'school', de: 'Schule' }, { w: 'friend', de: 'Freund' }, { w: 'water', de: 'Wasser' }] },
  { intro: vk('Schwierige Wörter! Achtung, nicht alle schreibt man so, wie man sie spricht.'), W: [{ w: 'butterfly', de: 'Schmetterling' }, { w: 'homework', de: 'Hausaufgaben' }, { w: 'Wednesday', de: 'Mittwoch' }] },
];
BLASEN.forEach((L) => L.W.forEach((x) => { x.k = vk(x.w, 'en'); if (x.de) x.q = vk(`Wie heißt ${x.de} auf Englisch?`); }));
function gBlasen(T) {
  gs.className = 'gs g-bub g-bub2';
  const L = BLASEN[G()]; let wi = 0, idx = 0, lock = true, raf, bubs = [], errsHere = 0;
  const fish = (k, cls) => `<img class="bfish ${cls}" src="/grundschulmax/sp/blas/${k}.webp" alt="" draggable="false">`;
  const minis = [...Array(9)].map((_, i) => `<img class="bmini" src="/grundschulmax/sp/blas/mini.webp" alt="" style="left:${(4 + i * 11.5 + Math.random() * 5).toFixed(1)}%;--s:${(.35 + Math.random() * .5).toFixed(2)};--d:${(7 + Math.random() * 7).toFixed(1)}s;--o:-${(Math.random() * 14).toFixed(1)}s">`).join('');
  gs.innerHTML = `<div class="gsky" style="--bg:url(/grundschulmax/sp/blas/bg.webp)"><i class="brays"></i>${fish('f0', 'bf1')}${fish('f1', 'bf2')}${fish('f0', 'bf3')}${minis}</div>
    <div class="bhd"><div class="bq" id="bq"></div><div class="slots" id="sl"></div></div><div id="bb"></div>`;
  const bb = $('#bb');
  function build() {
    const X = L.W[wi]; idx = 0; errsHere = 0;
    $('#bq').innerHTML = X.a ? `<div class="bp">${ART[X.a]}</div><button class="hear" id="bh" aria-label="Anhören">${I('snd')}</button>` : `<div class="bde"><small>Auf Englisch:</small><b>${X.de}</b></div><button class="hear" id="bh" aria-label="Anhören">${I('snd')}</button>`;
    $('#bh').onclick = () => voice(X.k, true);
    $('#sl').innerHTML = [...X.w].map(() => '<i></i>').join('');
    const letters = [...X.w.toLowerCase()];
    const extra = shuf([...'abcdefghijklmnoprstuvwy'].filter((c) => !letters.includes(c))).slice(0, X.w.length > 6 ? 2 : 3);
    bb.innerHTML = ''; bubs = shuf([...letters, ...extra]).map((ch) => { const el = document.createElement('button'); el.className = 'bub bub2'; el.innerHTML = `<img src="/grundschulmax/sp/blas/bub.webp" alt="" draggable="false"><b>${ch}</b>`; bb.appendChild(el); const b = { el, ch, ph: rnd(0, 6), sp: rnd(.5, .9), ax: 0, ay: 0, dead: false }; el.addEventListener('pointerdown', (e) => { e.preventDefault(); tap(b); }); return b; });
    place(); lock = false;
  }
  function place() {
    const Wd = gs.clientWidth, H = gs.clientHeight, mob = Wd < 600, s = mob ? 74 : 104, n = bubs.length;
    const hd = $('.bhd'), top = hd ? hd.offsetTop + hd.offsetHeight + 14 : 190;
    const x0 = mob ? 8 : 190, x1 = Wd - s - 10, bottom = Math.min(H - s - (mob ? 175 : 140), top + (Math.ceil(n / (mob ? 4 : 6)) - 1) * (s + 70));
    const cols = Math.max(2, Math.min(n, Math.floor((x1 - x0) / (s + 14)) + 1, mob ? 4 : 6)), rows = Math.ceil(n / cols);
    const avail = Math.max(0, bottom - top);
    shuf(bubs.map((_, i) => i)).forEach((slot, k) => { const b = bubs[k]; const r = Math.floor(slot / cols), c = slot % cols, off = r % 2 ? .25 : -.25; b.ax = x0 + ((c + .5 + (rows > 1 ? off : 0)) / cols) * (x1 - x0); b.ax = Math.max(x0, Math.min(x1, b.ax)); b.ay = top + (rows > 1 ? r / (rows - 1) : .5) * avail; });
  }
  function loop(ts) {
    if (!alive(T)) return;
    bubs.forEach((b) => { if (b.dead) return; b.el.style.transform = `translate(${b.ax + Math.sin(ts / 900 * b.sp + b.ph) * 10}px,${b.ay + Math.cos(ts / 1100 * b.sp + b.ph) * 9}px) rotate(${Math.sin(ts / 1300 + b.ph) * 4}deg)`; });
    raf = requestAnimationFrame(loop);
  }
  function tap(b) {
    if (lock || b.dead) return;
    const X = L.W[wi], want = X.w[idx];
    if (b.ch === want.toLowerCase()) {
      b.dead = true; sfx.pop();
      const slot = $$('#sl i')[idx];
      const im = b.el.querySelector('img'); im.src = '/grundschulmax/sp/blas/pop.webp'; b.el.classList.add('popd');
      const fl = b.el.querySelector('b'), a = fl.getBoundingClientRect(), z = slot.getBoundingClientRect();
      const ghost = document.createElement('b'); ghost.className = 'bghost'; ghost.textContent = want; ghost.style.left = a.left + 'px'; ghost.style.top = a.top + 'px'; ghost.style.width = a.width + 'px'; ghost.style.height = a.height + 'px'; document.body.appendChild(ghost); fl.style.opacity = 0;
      ghost.animate([{ transform: 'none' }, { transform: `translate(${z.left + z.width / 2 - a.left - a.width / 2}px,${z.top + z.height / 2 - a.top - a.height / 2}px) scale(.7)` }], { duration: 420, easing: 'cubic-bezier(.5,0,.7,1)', fill: 'forwards' })
        .onfinish = () => { ghost.remove(); slot.textContent = want; slot.classList.add('on'); };
      setTimeout(() => b.el.classList.add('gone'), 180);
      idx++;
      if (idx === X.w.length) {
        lock = true; right(true); setTimeout(sfx.ok, 300);
        setTimeout(() => { if (!alive(T)) return; restart($('#sl'), 'win'); voice(X.k); fb(true, okLineText(), X.de ? `${X.de} heißt „${X.w}“.` : `„${X.w}“`); dmax.className = 'dmax happy'; }, 450);
        setTimeout(() => { if (!alive(T)) return; wi++; if (wi < L.W.length) { build(); const N = L.W[wi]; if (N.q) voice(N.q); } else finish('Alle Wörter buchstabiert!', ['Erste englische Wörter hören und schreiben.', 'Längere Wörter richtig buchstabieren.', 'Deutsch denken, Englisch schreiben.', 'Schwere Wörter wie Wednesday: Das schafft nicht jeder!'][G()]); }, 2300);
      }
    } else {
      wrong(); errsHere++; sfx.no(); restart(b.el, 'shk'); say('Hör nochmal genau hin!', 'think'); voice(X.k);
      if (errsHere >= 2) { const s = $$('#sl i')[idx]; s.textContent = want; s.classList.add('hint'); }
    }
  }
  const okLineText = () => VL.get(pick(P.ok)).t;
  build(); lock = true;
  progress(L.W.length); sayK(L.intro);
  startOverlay('Blasen starten', '3 Wörter · Ton an, dann hörst du die Wörter', () => { lock = false; const X = L.W[0]; voice(X.q || X.k); });
  raf = requestAnimationFrame(loop);
  const ro = new ResizeObserver(place); ro.observe(gs);
  return () => { cancelAnimationFrame(raf); ro.disconnect(); document.querySelectorAll('.bghost').forEach((g) => g.remove()); };
}

/* ===================== FRANZÖSISCH ===================== */
WHO = 'claude';
const FRF = { rouge: ['rot', '#e8473c'], bleu: ['blau', '#2f6fe0'], vert: ['grün', '#2fae5c'], jaune: ['gelb', '#f5c518'], violet: ['lila', '#8a4fd6'], orange: ['orange', '#f39b52'], rose: ['rosa', '#f47ba0'], noir: ['schwarz', '#2a2a2a'], blanc: ['weiß', '#ffffff'] };
const KLECKS = [
  { intro: vk('Farbklecks-Fangen! Ich sage eine Farbe auf Französisch, du tippst den richtigen Klecks.'), items: ['rouge', 'bleu', 'vert', 'jaune', 'violet'].map((f) => ({ fr: f, de: FRF[f][0], c: FRF[f][1] })), show: 5, n: 5 },
  { intro: vk('Mehr Farben! Hör gut zu: Welcher Klecks ist gemeint?'), items: ['rouge', 'bleu', 'vert', 'jaune', 'orange', 'rose', 'noir', 'blanc'].map((f) => ({ fr: f, de: FRF[f][0], c: FRF[f][1] })), show: 6, n: 6 },
  { intro: vk('Zahlen auf Französisch! Tipp die richtige Zahl.'), items: [[7, 'sept'], [11, 'onze'], [12, 'douze'], [13, 'treize'], [15, 'quinze'], [16, 'seize'], [18, 'dix-huit'], [20, 'vingt']].map(([n, fr]) => ({ fr, de: String(n), c: pick(['#cfe4ff', '#ffd8e4', '#d9f5e3', '#fff1c2', '#e7ddff']), lab: n })), show: 6, n: 6 },
  { intro: vk('Tiere und Dinge auf Französisch! Was ist gemeint?'), items: [['le chat', 'die Katze', 'cat'], ['le poisson', 'der Fisch', 'fish'], ['la banane', 'die Banane', 'banane'], ['le soleil', 'die Sonne', 'sun'], ['la grenouille', 'der Frosch', 'frosch'], ['le renard', 'der Fuchs', 'fuchs'], ['le hibou', 'die Eule', 'eule'], ['le cochon', 'das Schwein', 'schwein']].map(([fr, de, a]) => ({ fr, de, c: '#ffffff', art: a })), show: 6, n: 6 },
];
KLECKS.forEach((L) => L.items.forEach((x) => { x.ask = vk(`Touche ${x.fr} !`, 'fr'); x.k = vk(x.fr, 'fr'); }));
const vkTresBien = vk('Très bien !', 'fr');
function gFarben(T) {
  gs.className = 'gs g-fr g-fr2';
  const L = KLECKS[G()], order = shuf(L.items).slice(0, L.n);
  let r = 0, lock = true, raf, blobs = [];
  gs.innerHTML = `${SKY('farb', [[0, 6.5, 2, 26, 359], [1, 75.9, 6.6, 34, 368], [2, 68.1, 15.2, 40, 118], [3, 24.5, 21.9, 30, 256], [4, 48.9, 33.3, 44, 125], [5, 75.2, 35.7, 38, 128]], [], 1920)}<img class="feim" src="/grundschulmax/sp/farb/eimer.webp" alt=""><img class="fpin" id="fpin" src="/grundschulmax/sp/farb/pinsel.webp" alt=""><div class="ask"><span>Touche&nbsp;…</span><b id="fw"></b><button id="fh" aria-label="Anhören">${I('snd')}</button></div><div id="bb"></div>`;
  const bb = $('#bb');
  function mk() {
    const target = order[r], others = shuf(L.items.filter((x) => x !== target)).slice(0, L.show - 1), set = shuf([target, ...others]);
    bb.innerHTML = ''; blobs = set.map((c) => {
      const el = document.createElement('div'); el.className = 'blb blb2' + (c.art ? ' bimg' : '');
      const inner = c.lab ? `<text x="50" y="62" text-anchor="middle" font-family="G,system-ui,sans-serif" font-weight="900" font-size="36" fill="#2a2a4a">${c.lab}</text>` : '';
      const sk = FRF[c.fr] ? c.fr : c.art ? 'blanc' : (c.sk || (c.sk = pick(['bleu', 'rose', 'vert', 'orange', 'violet', 'rouge'])));
      el.innerHTML = `<img class="spi" src="/grundschulmax/sp/farb/${sk}.webp" alt="" draggable="false">` + (c.lab ? `<b class="bnum">${c.lab}</b>` : '') + (c.art ? `<div class="bart">${ART[c.art]}</div>` : '');
      if (c.c === '#ffffff') el.classList.add('white');
      bb.appendChild(el);
      const b = { el, c, x: 0, y: 0, ax: 0, ay: 0, ph: rnd(0, 6), sp: rnd(.5, .9) };
      el.addEventListener('pointerdown', (e) => { e.preventDefault(); hit(b); });
      return b;
    });
    place();
  }
  function place() {
    const W = gs.clientWidth, H = gs.clientHeight, mob = W < 600, cols = mob ? 2 : 3, rows = Math.ceil(6 / cols), x0 = mob ? 6 : 200, y0 = mob ? 76 : 90, yb = mob ? 170 : 40, s = Math.max(64, Math.min(mob ? 110 : 130, (H - y0 - yb) / (rows + 1.15)));
    blobs.forEach((b) => { if (s < (mob ? 110 : 130)) { b.el.style.setProperty('width', s + 'px', 'important'); b.el.style.setProperty('height', s + 'px', 'important'); } else { b.el.style.removeProperty('width'); b.el.style.removeProperty('height'); } });
    const spots = shuf([...Array(6)].map((_, i) => ({ x: (i % cols + .5) / cols, y: (Math.floor(i / cols) + .5) / Math.ceil(6 / cols) })));
    blobs.forEach((b, i) => { b.ax = x0 + spots[i].x * (W - x0 - s - 20) - s / 2 + s / 2; b.ay = y0 + spots[i].y * Math.max(60, H - y0 - yb - s); b.el.classList.remove('spl', 'no'); });
  }
  function loop(ts) {
    if (!alive(T)) return;
    blobs.forEach((b) => { b.x = b.ax + Math.sin(ts / 900 * b.sp + b.ph) * 20; b.y = b.ay + Math.cos(ts / 1100 * b.sp + b.ph) * 12; b.el.style.transform = `translate(${b.x}px,${b.y}px)`; });
    raf = requestAnimationFrame(loop);
  }
  function ask() {
    const w = $('#fw'); w.textContent = order[r].fr; restart(w, 'nw');
    say(`Touche ${order[r].fr} !`, '', order[r].ask); lock = false;
  }
  function label(b, txt, col) { const l = document.createElement('div'); l.className = 'lbl'; l.style.left = b.x + b.el.offsetWidth / 2 + 'px'; l.style.top = b.y + 'px'; l.style.color = col; l.textContent = txt; gs.appendChild(l); setTimeout(() => l.remove(), 1100); }
  function dab(b) {
    const pn = $('#fpin'); if (!pn) return; const gr = gs.getBoundingClientRect(), pr = pn.getBoundingClientRect();
    const dx = b.x + b.el.offsetWidth * .5 - (pr.left - gr.left) - pr.width * .2, dy = b.y + b.el.offsetHeight * .45 - (pr.top - gr.top);
    pn.animate([{ transform: 'none' }, { transform: `translate(${dx}px,${dy}px) rotate(-25deg)`, offset: .45 }, { transform: `translate(${dx + 8}px,${dy + 10}px) rotate(-35deg)`, offset: .55 }, { transform: 'none' }], { duration: 900, easing: 'ease-in-out' });
  }
  function hit(b) {
    if (lock) return;
    if (b.c === order[r]) {
      lock = true; dab(b); setTimeout(() => { b.el.classList.add('spl'); sfx.pop(); }, 260); setTimeout(sfx.ok, 360);
      setTimeout(() => burst(b.x + b.el.offsetWidth / 2, b.y + b.el.offsetHeight / 2, b.c.c === '#ffffff' ? ['#9b7cf0', '#f47ba0'] : b.c.c, 18), 260);
      right(); voice(vkTresBien); dmax.className = 'dmax happy'; sayEl.textContent = 'Très bien !';
      fb(true, 'Très bien !', `${b.c.fr} = ${b.c.de}`);
      setTimeout(() => { if (!alive(T)) return; r++; if (r < order.length) { mk(); ask(); } else finish('Bravo !', ['Fünf Farben auf Französisch: hören und erkennen.', 'Acht Farben auf Französisch sicher erkannt.', 'Zahlen bis zwanzig auf Französisch.', 'Tiere und Dinge mit Artikel: le und la.'][G()]); }, 1200);
    } else {
      wrong(); restart(b.el, 'no'); sfx.no(); label(b, b.c.fr, b.c.c === '#ffffff' ? '#5b3fc4' : b.c.c);
      say(`Das ist ${b.c.fr}, also ${b.c.de}. Wir suchen ${order[r].fr}!`, 'think', b.c.k);
      fb(false, 'Fast!', `Das ist ${b.c.fr} (${b.c.de}).`, { ms: 1800 });
    }
  }
  $('#fh').onclick = () => voice(order[r].ask, true);
  mk(); raf = requestAnimationFrame(loop);
  $('#fw').textContent = order[0].fr;
  progress(order.length); sayK(L.intro);
  startOverlay('Kleckse fangen', `${order.length} Runden · hören und tippen`, ask);
  const ro = new ResizeObserver(place); ro.observe(gs);
  return () => { cancelAnimationFrame(raf); ro.disconnect(); };
}

/* Le petit café: Bestellungen auf Französisch servieren */
const CAFE_IT = { croissant: ['un croissant', 'Croissant', 'croissant'], baguette: ['une baguette', 'Baguette', 'baguette'], cafe: ['un café', 'Kaffee', 'café'], chocolat: ['un chocolat', 'Kakao', 'chocolat'], crepe: ['une crêpe', 'Crêpe', 'crêpe'], glace: ['une glace', 'Eis', 'glace'], jus: ['un jus d’orange', 'Orangensaft', 'jus'], eau: ['un verre d’eau', 'Wasser', 'eau'] };
