    if (r >= N) return finish('Fließband geschafft!', ['Nomen und Verben unterscheiden.', 'Nomen, Verben und Adjektive sortieren.', 'Wortarten sicher erkennen.', 'Wortarten blitzschnell sortieren.'][G()]);
    cur = Q[r]; $('#bt').innerHTML = `<div class="bword" id="bw">${G() > 0 ? cur[0].toUpperCase() : cur[0]}</div>`; el = $('#bw'); restart(el, 'ride'); sfx.chug(); restart($('.gsky', gs), 'run');
