/* ---------- Gemeinsame Helfer für die neuen Sprach-Spiele ---------- */
/* Beste verfügbare Gerätestimme wählen (natürliche/erweiterte Stimmen zuerst) */
function bestVoice(lang) { try { const L = speechSynthesis.getVoices().filter((x) => x.lang && x.lang.toLowerCase().replace('_', '-').startsWith(lang.slice(0, 2).toLowerCase())); if (!L.length) return null;
  const sc = (v) => (/natural|neural|premium|enhanced|erweitert|siri/i.test(v.name) ? 40 : 0) + (/google/i.test(v.name) ? 25 : 0) + (v.lang.toLowerCase().replace('_', '-') === lang.toLowerCase() ? 10 : 0) + (/anna|petra|helena|katja|serena|daniel|kate|amelie|thomas|audrey/i.test(v.name) ? 8 : 0) - (/compact|espeak/i.test(v.name) ? 30 : 0);
  return L.sort((a, b) => sc(b) - sc(a))[0]; } catch (e) { return null; } }

/* Nur echte Aufnahmen der Tutoren abspielen. Gibt es keine, wird nichts mit der Gerätestimme gesprochen, sondern der Text gezeigt. */
