    $('#xo').innerHTML = cur.o.map((o, i) => `<button class="xo${o.html ? ' scn' : o.img ? '' : ' txt'}${!o.img && !o.html && o.label && o.label.length > 16 ? ' lng' : ''}" data-k="${o.k}" style="--dl:${.25 + i * .09}s">${o.html || (o.img ? `<img src="${o.img}" alt="">` : '')}${o.label ? `<span>${o.label}</span>` : ''}</button>`).join('');
    $$('.xo', gs).forEach((b) => (b.onclick = () => pick(b)));
    requestAnimationFrame(() => $$('.etx', gs).forEach((el) => { el.style.fontSize = ''; let f = parseFloat(getComputedStyle(el).fontSize), k = 0; while (el.scrollHeight > el.clientHeight + 2 && f > 14 && k++ < 30) { f *= .92; el.style.fontSize = f + 'px'; } }));
    if (!$('#xq .xhear')) { const qt = $('#xq b'); if (qt) { $('#xq').insertAdjacentHTML('afterbegin', hearBtn()); const t0 = qt.textContent; $('#xq .xhear').onclick = () => ttsDe(t0, true); } }
