    if (ok) { right(); sfx.coin(); b.classList.add('ok'); xBurst(b); xWord(opt.okWord ? opt.okWord(cur) : ['Super!', 'Richtig!', 'Klasse!', 'Yes!'][r % 4], b); }
    else { wrong(); sfx.no(); b.classList.add('no'); const c = $(`.xo[data-k="${cur.a}"]`, gs); if (c) c.classList.add('hint'); }
    $$('.xo', gs).forEach((x) => x !== b && !x.classList.contains('hint') && x.classList.add('dim'));
    if (opt.onPick) opt.onPick(ok, cur, b);
