/* ---------- Wie lernt eine KI? ---------- */
function gKiLern(T) {
  gs.className = 'gs g-xs g-kil';
  const D = 'kil', g = G();
  const SCH = [['t', 't', 't', 't', 'x', 'x', 'x'], ['t', 't', 't', 't', 'x', 'x', 'x'], ['t', 't', 't', 'x', 'x', 'q', 'q'], ['t', 't', 't', 'x', 'x', 'q', 'q']][g], N = SCH.length;
  const QZ = shuf([['Wie lernt eine KI?', ['Mit ganz vielen Beispielen', 'Sie weiß alles von Anfang an', 'Durch Zaubersprüche']], ['Kann eine KI Fehler machen?', ['Ja, deshalb prüft man besser nach', 'Nein, niemals', 'Nur am Wochenende']], ['Wer zeigt einer KI, was richtig ist?', ['Menschen, die ihr Beispiele geben', 'Niemand, sie weiß es einfach', 'Die Tiere selbst']]].concat(g >= 3 ? [['Eine KI hat nur Bilder von Hunden gesehen. Was passiert bei einer Katze?', ['Sie hält die Katze vielleicht für einen Hund', 'Sie erkennt die Katze sofort', 'Sie geht kaputt']]] : []));
  let learned = 0, qi = 0;
  gs.innerHTML = `<div class="gsky" style="--bg:url(${xImg(D, 'bg')})"></div><img class="kgear" id="kgr" src="${xImg(D, 'gear')}" alt=""><div class="kcube" id="kcb"><img src="${xImg(D, 'cube')}" alt=""><b id="kcn">0</b></div><img class="kbulb" id="kbl" src="${xImg(D, 'bulb')}" alt=""><img class="kbot" id="kbt" src="${xImg(D, 'rthink')}" alt=""><div class="kcard" id="kcd"></div><div class="xq" id="xq"></div><div class="xopts" id="xo"></div>`;
  const card = (k, guess) => { $('#kcd').innerHTML = k ? `<img src="${xImg(D, k === 'cat' ? 'catc' : 'dogc')}" alt="">${guess ? `<span class="kguess">${guess}</span>` : ''}` : ''; if (k) restart($('#kcd'), 'pop'); };
  const next = xRound(T, { N, done: 'Bit hat viel gelernt!', doneT: ['Eine KI lernt aus Beispielen.', 'Mit Beispielen lernt eine KI.', 'Lernen, testen, verbessern.', 'So lernen echte KIs.'], okMs: 1500,
    onShow: () => { $('#kbt').src = xImg(D, 'rthink'); },
    make: (r) => { const t = SCH[r];
      if (t === 't') { const k = Math.random() < .5 ? 'cat' : 'dog'; card(k); return { html: `<b>Bring Bit bei: Was ist auf dem Bild?</b><small>Bit lernt aus deinen Beispielen.</small>`, o: [{ k: 'cat', label: 'Katze' }, { k: 'dog', label: 'Hund' }], a: k, okT: `Bit merkt sich: Das ist ${k === 'cat' ? 'eine Katze' : 'ein Hund'}!`, noT: 'Ups! Mit falschen Beispielen lernt eine KI Falsches.', _t: 't' }; }
      if (t === 'x') { const k = Math.random() < .5 ? 'cat' : 'dog', right0 = Math.random() < .5 + learned * .08, gu = right0 ? k : k === 'cat' ? 'dog' : 'cat'; card(k, `Ich glaube: ${gu === 'cat' ? 'Katze' : 'Hund'}!`); return { html: `<b>Test! Hat Bit richtig geraten?</b><small>Schau dir das Bild genau an.</small>`, o: [{ k: 'y', label: 'Stimmt' }, { k: 'n', label: 'Stimmt nicht' }], a: right0 ? 'y' : 'n', okT: right0 ? 'Bit hat richtig gelernt!' : 'Gut aufgepasst! Auch eine KI macht Fehler. Darum prüfen wir nach.', noT: right0 ? 'Doch, Bit lag richtig.' : 'Bit hat sich geirrt! Eine KI kann Fehler machen.', _t: 'x' }; }
      card(''); const q = QZ[qi++ % QZ.length]; return { html: `<b>${q[0]}</b>`, o: tOpts(q[1]), a: '0', okT: 'Genau!', noT: `Richtig ist: ${q[1][0]}.`, _t: 'q' }; },
    onPick: (ok, cur) => { const b = $('#kbt'); b.src = xImg(D, ok ? 'rhappy' : 'rques'); restart(b, ok ? 'yay' : 'shake');
      if (ok && cur._t === 't') { learned++; $('#kcn').textContent = learned; const c = $('#kcd img'); if (c) { const a = c.getBoundingClientRect(), z = $('#kcb').getBoundingClientRect(); c.animate([{ transform: 'none' }, { transform: `translate(${z.left - a.left + z.width / 2 - a.width / 2}px,${z.top - a.top + z.height / 2 - a.height / 2}px) scale(.2)`, opacity: .2 }], { duration: 650, easing: 'cubic-bezier(.5,0,.6,1)', fill: 'forwards' }); } setTimeout(() => { restart($('#kcb'), 'gulp'); restart($('#kgr'), 'spin'); restart($('#kbl'), 'glow'); }, 620); }
      if (ok && cur._t !== 't') restart($('#kbl'), 'glow'); } });
  progress(N); say('Hilf Bit beim Lernen! Zeig ihm Beispiele und teste ihn dann.', '');
  startOverlay('Training starten', `${N} Runden · So lernt eine KI`, next);
  return () => {};
}

/* ---------- Echt oder erfunden? ---------- */
function gEcht(T) {
  gs.className = 'gs g-xs g-echt';
  const D = 'echt', g = G(), N = 8;
  const S0 = [[1, 'Bienen machen Honig.', 'Das stimmt! Bienen machen aus Blütensaft Honig.'], [1, 'Pinguine leben dort, wo es kalt ist.', 'Stimmt, viele Pinguine leben am kalten Meer rund um die Antarktis.'], [0, 'Ein Foto zeigt einen Hund, so groß wie ein Haus.', 'So große Hunde gibt es nicht. Das Bild ist erfunden.', 1], [0, 'Ein Video zeigt eine Katze, die Auto fährt.', 'Katzen können nicht Auto fahren. Das ist erfunden.', 1], [1, 'Nach dem Regen sieht man manchmal einen Regenbogen.', 'Das stimmt!'], [0, 'Im Internet steht: Kühe können fliegen.', 'Nicht alles im Internet stimmt!'], [1, 'Im Herbst werden viele Blätter bunt.', 'Das stimmt!'], [0, 'Ein Bild zeigt einen Elefanten, der auf einem dünnen Ast sitzt.', 'Das geht nicht. Das Bild ist erfunden.', 1]];
  const S1 = [[0, 'Auf einem Foto hat ein Mensch sechs Finger an einer Hand.', 'Zu viele Finger sind ein typischer Fehler von KI-Bildern.', 1], [0, 'Eine Nachricht sagt: Morgen ist für immer schulfrei! Schick das sofort an alle!', 'Wenn man etwas sofort an alle schicken soll, ist es oft erfunden.'], [0, 'Auf einem Schild im Bild stehen nur seltsame, verdrehte Buchstaben.', 'Komische Schrift ist ein Hinweis auf ein KI-Bild.', 1], [1, 'Die Erde dreht sich um die Sonne.', 'Das stimmt!'], [1, 'Wale sind Säugetiere.', 'Stimmt! Wale atmen Luft und trinken als Baby Milch.'], [0, 'Ein Video zeigt einen Fisch, der Fahrrad fährt.', 'Das ist erfunden.', 1], [1, 'Wasser kocht bei 100 Grad.', 'Das stimmt!'], [0, 'Ein Bild zeigt einen Hund, dessen Pfoten mit dem Boden verschmelzen.', 'Verschwommene, verschmolzene Stellen verraten oft KI-Bilder.', 1]];
  const L = shuf(g <= 1 ? S0 : g === 2 ? shuf(S0).slice(0, 3).concat(S1.slice(0, 6)) : S1).slice(0, N);
  gs.innerHTML = `<div class="gsky" style="--bg:url(${xImg(D, 'bg')})"></div><div class="eframe" id="efr"><img class="efb" src="${xImg(D, 'frame')}" alt=""><div class="etx" id="etx"></div><img class="ecam" id="ecm" src="${xImg(D, 'cam')}" alt=""></div><img class="ecat" id="ect" src="${xImg(D, 'cat')}" alt=""><img class="eloupe" id="elp" src="${xImg(D, 'loupe')}" alt=""><img class="eques" src="${xImg(D, 'ques')}" alt=""><div class="xq" id="xq"></div><div class="xopts" id="xo"></div>`;
  const next = xRound(T, { N, done: 'Super Detektiv-Arbeit!', doneT: ['Was echt ist und was erfunden.', 'Nicht alles im Internet stimmt.', 'KI-Bilder und Falschmeldungen erkennen.', 'Wie ein Profi nachprüfen.'], okMs: 1800,
    make: (r) => { const s = L[r]; $('#etx').textContent = s[1]; $('#ecm').style.display = s[3] ? '' : 'none'; restart($('#efr'), 'pop'); $$('.estamp', gs).forEach((e) => e.remove());
      return { html: `<b>Echt oder erfunden?</b><small>Lies genau und denk nach.</small>`, o: [{ k: '1', img: xImg(D, 'ok'), label: 'Echt' }, { k: '0', img: xImg(D, 'no'), label: 'Erfunden' }], a: String(s[0]), okT: s[2], noT: s[2] }; },
    onPick: (ok, cur) => { const f = $('#efr'), st = document.createElement('img'); st.src = xImg(D, cur.a === '1' ? 'ok' : 'no'); st.className = 'estamp'; f.appendChild(st); restart($('#elp'), 'scan'); restart($('#ect'), ok ? 'yay' : 'shake'); if (cur.a === '0') xFly(xImg(D, 'glitch'), f, 'eglitch', 900); } });
  progress(N); say('Werde Detektiv! Ist das echt oder erfunden?', '');
  startOverlay('Fall starten', `${N} Fälle · Echt oder erfunden?`, next);
  return () => {};
}

/* ---------- Lernpfad wie bei Duolingo: Level -> 4 Lektionen -> Spiel ---------- */
const LPKEY = 'gsm-lp2', LV_FREE = 2, PER = 5; // 2 Level frei in der Vorschau, je Level 4 Lektionen + 1 Spiel
let LPS = {}; try { LPS = JSON.parse(localStorage.getItem(LPKEY) || '{}') || {}; } catch (e) { LPS = {}; }
const lpSave = () => { try { localStorage.setItem(LPKEY, JSON.stringify(LPS)); } catch (e) {} };
const lpProg = (k, g) => (LPS[k + g] = LPS[k + g] || { n: 0, xp: 0 });
/* Level 7–20 haben keinen eigenen Stoff: ehrlich als Wiederholung beschriften */
/* Internet & KI: 6 Themen-Level, 2 Wiederholungen, dann der Abschlusstest (Internet-Führerschein). Andere Fächer unverändert. */
const LPC = {};
