  const u100 = (v) => v < 20 ? E[v] : (v % 10 ? (v % 10 === 1 ? 'ein' : E[v % 10]) + 'und' : '') + Z[Math.floor(v / 10)];
  const u1000 = (v) => (v >= 100 ? (Math.floor(v / 100) === 1 ? 'ein' : E[Math.floor(v / 100)]) + 'hundert' : '') + (v % 100 ? u100(v % 100) : '');
