  const L = list.filter((k) => k && CLIPS[(who || 'max') + '|' + k]); let i = 0;
  const next = () => { if (i >= L.length || !LS) return; const k = L[i++]; const ok = voice(k, force, who); const a = curAudio; if (ok && a) a.onended = () => { talk(false); if (curAudio === a) setTimeout(next, 300); }; };
