  const who = (LS && LS.who) || 'max', parts = String(text || '').split(/(?<=[.!?])\s+/).map((t) => t.trim()).filter(Boolean);
  const ks = parts.map((t) => ['de:' + t, 'fr:' + t, 'en:' + t].find((k) => CLIPS[who + '|' + k]) || null);
