  const say = (slow) => { stopVoice(); const b = $$('.lspk', h)[slow ? 1 : 0]; if (!b || !b.isConnected) return; restart(b, 'xplay'); const url = CLIPS[SUBJ[st.s].tutor.id + '|' + x.vs]; if (url) { curAudio = freshAudio(url); if (slow) curAudio.playbackRate = .72; curAudio.play().catch(() => {}); return; } if (typeof noSoundView === 'function') noSoundView(x, h); };
