  h.innerHTML = `<div class="gapc">${glueGap(parts[0], '<span class="gslot0" id="gslot"></span>', parts.slice(1).join('___'))}</div><div class="chips">${o.map((t, i) => `<button class="chip" data-v="${i}">${t}</button>`).join('')}</div>`;
