      sfx.coin(); restart(bin, 'gulp'); { const bc = $('.bct', bin); bc.insertAdjacentHTML('beforeend', `<i>${it[0]}</i>`); while (bc.children.length > 2) bc.firstElementChild.remove(); } i++; const lp = $('.slamp', h); if (lp) restart(lp, 'flash'); const sh = $('.srt', h) || h, sr = sh.getBoundingClientRect(), spk = document.createElement('img'); spk.className = 'sspk'; spk.src = '/grundschulmax/sp/belt2/spark.webp'; spk.style.left = b.left + b.width / 2 - sr.left + 'px'; spk.style.top = b.top + 10 - sr.top + 'px'; sh.appendChild(spk); setTimeout(() => spk.remove(), 800);
      setTimeout(() => { if (!alive(ctx.T)) return; if (i < items.length) show(); else { $$('.srti', sc).forEach((e) => e.remove()); ctx.auto(true); } }, 420);
