      const otx = (e) => { const c = e.cloneNode(true); c.querySelectorAll('kbd, svg').forEach((k) => k.remove()); return c.textContent.replace(/\s+/g, ' ').trim(); }, sol = String(solText(x)).replace(/\s+/g, ' ').trim();
      const wrong = opts.filter((e) => otx(e) !== sol && !(x.k === 'tf'));
      if (wrong.length > 1 && tips <= 2) { const w = wrong[Math.floor(Math.random() * wrong.length)]; w.classList.add('gone'); w.style.pointerEvents = 'none'; lesSay(tips === 1 ? 'Eine Antwort ist schon mal falsch. Die habe ich weggenommen.' : 'Noch eine weg. Jetzt schaffst du es!', null, 'think'); }
      else { const t = x.h || (x.k === 'tf' ? 'Lies die Aussage noch einmal Wort für Wort. Stimmt wirklich alles daran?' : x.e && !/^(genau|richtig|stimmt|falsch|nein|ja)\b/i.test(String(x.e).trim()) && !String(x.e).split(/(?<=[.!?])\s/)[0].toLowerCase().includes(String(solText(x)).toLowerCase()) ? String(x.e).split(/(?<=[.!?])\s/)[0] : 'Lies die Aufgabe noch einmal ganz langsam.'); lesSay('Tipp: ' + t, null, 'think'); }
