/* ---------- Endbildschirm: große 3D-Sterne, glänzende Karten, alles im Takt mit dem Ton ---------- */
function endShow(e) {
  const U = (k) => `/grundschulmax/sp/${k}.webp`, bs = $('.bs', e), n = bs ? $$('svg.on', bs).length : 0;
  if (bs) bs.outerHTML = `<div class="es-stars">${[0, 1, 2, 3, 4].map((i) => `<span class="es-st${i < n ? ' on' : ''}"><img class="es-off" src="${U('rew/staroff')}" alt=""><img class="es-on" src="${U('rew/star')}" alt=""></span>`).join('')}</div>`;
  const ls = $('.lestats', e);
  if (ls) { const ic = { lsx: 'rew/coins', lsa: 'rew/medal', lst: 'rew/clock' };
    $$('.lestats>div', e).forEach((d) => { const k = d.className.split(' ')[0]; d.insertAdjacentHTML('afterbegin', `<img class="es-ic" src="${U(ic[k] || 'ui/star')}" alt=""><i class="es-gl"></i>`); }); }
  e.insertAdjacentHTML('afterbegin', `<div class="es-rays"></div><img class="es-rimg" src="${U('rew/rays')}" alt="">`);
  const g = window.gsap, stars = $$('.es-st', e), on = stars.filter((s) => s.classList.contains('on')), cards = $$('.lestats>div', e), go = $('[data-a=go], [data-a=pay]', e);
  const tick = (i) => { try { tone(660 + i * 140, .14, 'triangle', .09); setTimeout(() => tone(990 + i * 160, .08, 'sine', .05), 60); } catch (er) {} };
  const count = (b, d) => { const m = b.textContent.match(/^(\D*)(\d+)(.*)$/); if (!m || b.closest('.lst')) return; const n0 = +m[2], o = { v: 0 }; b.textContent = m[1] + '0' + m[3]; if (g) g.to(o, { v: n0, duration: d, ease: 'power2.out', onUpdate: () => { b.textContent = m[1] + Math.round(o.v) + m[3]; } }); };
  if (!g) { on.forEach((s, i) => setTimeout(() => { s.classList.add('in'); tick(i); }, 400 + i * 260)); return; }
  const tl = g.timeline({ delay: .25 });
  tl.from($('.lee', e), { scale: .85, opacity: 0, duration: .45, ease: 'back.out(1.8)' });
  stars.forEach((s) => g.set($('.es-on', s), { scale: 0, rotation: -120, opacity: 0 }));
  on.forEach((s, i) => {
    const im = $('.es-on', s);
    tl.to(im, { keyframes: [{ scale: 1.55, rotation: 15, opacity: 1, duration: .22, ease: 'power2.out' }, { scale: 1, rotation: 0, duration: .35, ease: 'elastic.out(1,.45)' }], onStart: () => { tick(i); s.classList.add('in'); const r = s.getBoundingClientRect(); for (let k = 0; k < 10; k++) { const p = document.createElement('i'); p.className = 'es-sp'; p.style.left = r.left + r.width / 2 + 'px'; p.style.top = r.top + r.height / 2 + 'px'; document.body.appendChild(p); g.to(p, { x: Math.cos(k / 10 * 6.28) * (50 + Math.random() * 40), y: Math.sin(k / 10 * 6.28) * (50 + Math.random() * 40), scale: 0, duration: .7, ease: 'power2.out', onComplete: () => p.remove() }); } } }, i ? '-=.25' : '+=.05');
  });
  tl.add(() => { try { sfx.win(); } catch (er) {} if (on.length >= 4) confetti(on.length === 5 ? 110 : 60); const c = $('.es-stars', e); if (!c) return; const r = c.getBoundingClientRect(); for (let k = 0; k < 6; k++) { const im = document.createElement('img'); im.src = U('rew/confetti'); im.className = 'es-cf'; im.style.left = r.left + r.width / 2 + 'px'; im.style.top = r.top + r.height / 2 + 'px'; document.body.appendChild(im); g.fromTo(im, { scale: .2, rotation: 0, opacity: 1 }, { x: (Math.random() - .5) * 520, y: (Math.random() - .7) * 340, scale: .6 + Math.random() * .5, rotation: (Math.random() - .5) * 400, opacity: 0, duration: 1.4, ease: 'power2.out', onComplete: () => im.remove() }); } }, '-=.1');
  tl.from(cards, { y: 40, scale: .6, opacity: 0, duration: .5, stagger: .14, ease: 'back.out(2)', onStart: () => cards.forEach((c, i) => setTimeout(() => { $$('b', c).forEach((b) => count(b, .9)); try { tone(520 + i * 90, .1, 'sine', .06); } catch (er) {} }, i * 140)) }, '+=.1');
  const par = $('.lepar', e); if (par) tl.from(par, { y: 18, opacity: 0, duration: .4, ease: 'power2.out' }, '+=.05');
  const btns = $$('[data-a]', e); if (btns.length) tl.fromTo(btns, { scale: 0, opacity: 0 }, { scale: 1, opacity: 1, duration: .45, stagger: .08, ease: 'back.out(2.2)', immediateRender: true, onComplete: () => g.set(btns, { clearProps: 'transform,opacity,scale' }) }, '+=.05');
  /* Sicherheitsnetz: Knöpfe sind nach spätestens 4 s immer sichtbar und klickbar */
  setTimeout(() => { if (!e.isConnected) return; try { tl.progress(1); } catch (er) {} g.set($$('[data-a], .lee, .lestats>div, .lepar', e), { clearProps: 'opacity,transform,scale' }); }, 6500);
  tl.add(() => { try { voice(P.st[Math.min(5, Math.max(1, on.length)) - 1], false, LS && LS.who); } catch (er) {} });
}

