    $('.fxmc', ov).innerHTML = `<span class="fxrvi big">${FX.check}</span><h2>Vielen Dank!</h2><p class="fxlead">Ihre Bewertung ist bei uns angekommen. Sie hilft anderen Eltern bei der Entscheidung.</p><button type="button" class="fxbtn" id="fxrc">Zurück zur Übersicht</button>`;
    $('#fxrc', ov).onclick = () => { close(); if (fsOpen.draw) fsOpen.draw(); };
