  e.innerHTML = `<div class="fxe"><div class="fxeh">${FX.logo}<span>${fsCur().n}</span></div><h3>${head}</h3><p>${body}</p>
    ${neu ? `<div class="fxenew"><i>${FX.check}</i><span><small>Neu auf deinem Führerschein</small><b>${neu}</b></span></div>` : ''}
    <div class="fxest"><div><b>${right} von ${tot}</b><small>richtig</small></div><div><b>${acc} %</b><small>Genauigkeit</small></div><div><b>${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}</b><small>Zeit</small></div></div>
    <div class="fxeb">${btns}</div></div>`;
  $('.lesin', les).appendChild(e); $('.lestut', les).className = 'lestut happy';
  const back = () => { closeLesson(); fsOpen(); };
  $('[data-a=back]', e).onclick = back;
  const nx = $('[data-a=next]', e); if (nx) nx.onclick = () => { closeLesson(); fsOpen(); const j = FS_PLAN.findIndex((y, k) => fsStat(g, k) === 'c'); if (j >= 0) setTimeout(() => fsUnit(j), 350); };
  const ce = $('[data-a=cert]', e); if (ce) ce.onclick = () => fsUrkunde(fsKl(), fsOk()[g + 1], fsC());
