function markTried() { try { localStorage.setItem('gsm-tried', '1'); } catch (e) {} document.body.classList.add('did1'); const sp = document.getElementById('spot'); if (sp) sp.classList.remove('on'); }
try { if (localStorage.getItem('gsm-tried')) document.body.classList.add('did1'); } catch (e) {}
