/* ---------- Abenteuer-Pfad: alle Fächer gemischt, jede Station ein anderes Fach ---------- */
const MIX_ORDER = ['ki', 'englisch', 'mathe', 'deutsch', 'sach', 'franz'], MIX_FREE = 3, MIX_AHEAD = 14;
const MIX_X = [0, 140, 210, 140, 0, -140, -210, -140];
let MIXRUN = null;
const mixSt = () => { LPS._mix = LPS._mix || {}; const m = LPS._mix; m.off = m.off || []; m.d = m.d || {}; return m; };
const mixLes = (k, g) => { const out = []; lpLevels(k, g).forEach((lv, li) => (lv.L || []).forEach((_, j) => out.push({ li, j, t: lv.t, d: lv.d || '' }))); return out; };
const mixDone = () => { const m = mixSt(); return Object.values(m.d).reduce((a, b) => a + b, 0); };
function mixStations(g) {
  const m = mixSt(), act = MIX_ORDER.filter((k) => !m.off.includes(k) && mixLes(k, g).length), A = act.length, out = [];
  if (!A) return out;
  const L = {}; act.forEach((k) => (L[k] = mixLes(k, g)));
  const R = Math.max(...act.map((k) => L[k].length));
  for (let r = 0; r < R; r++) for (let i = 0; i < A; i++) {
    const k = act[A > 2 ? (r + i) % A : i]; if (r >= L[k].length) continue;
    out.push({ k, r, ...L[k][r], done: r < (m.d[k + g] || 0) });
  }
  return out;
}
