/* Figuren blinzeln: kurz das Bild mit geschlossenen Augen zeigen */
(() => {
  const B = new Set(['bonj/boy','bonj/cat','clock2/owl','eshop/bear','eshop/teddy','goal2/keep','hupf/frog','hupf/jump','katze/jump','katze/peek','mole2/sign','planet2/astro','pong/frog','pong/hase','pong/pad','simon/sit','story/bunny','story/fox','story/owl']), pre = {};
  const key = (im) => { try { const p = new URL(im.currentSrc || im.src, location.href).pathname; const m = p.match(/\/grundschulmax\/sp\/(.+)\.webp$/); return m && B.has(m[1]) ? m[1] : null; } catch (e) { return null; } };
  setInterval(() => {
    if (document.hidden || !document.querySelector('#stage.open, .les.on')) return; const now = Date.now();
    document.querySelectorAll('#gs img, .les img, #stage img').forEach((im) => {
      if (im.dataset.bl === '1') return; const k = key(im); if (!k) return;
      if (!pre[k]) { pre[k] = new Image(); pre[k].src = '/grundschulmax/sp/' + k + '-b.webp'; }
      if (!im._nb) { im._nb = now + 1200 + Math.random() * 3000; return; }
      if (now < im._nb || !pre[k].complete) return;
      const orig = im.getAttribute('src'); im.dataset.bl = '1'; im.src = '/grundschulmax/sp/' + k + '-b.webp';
      const dbl = Math.random() < .2;
      setTimeout(() => { if (im.getAttribute('src').endsWith(k + '-b.webp')) im.src = orig; if (dbl) setTimeout(() => { im.src = '/grundschulmax/sp/' + k + '-b.webp'; setTimeout(() => { if (im.getAttribute('src').endsWith(k + '-b.webp')) im.src = orig; im.dataset.bl = ''; }, 110); }, 140); else im.dataset.bl = ''; }, 120);
      im._nb = now + 2600 + Math.random() * 3200;
    });
  }, 200);
})();

