/* ---------- Lektionen als Spiele: jede Lektion eine eigene Welt, jede Aufgabe ein Spiel ---------- */
const WORLDS = [
  { k: 'meer', n: 'Unterwasser-Welt', skins: ['fish', 'chest', 'frog'] },
  { k: 'wiese', n: 'Wiesen-Welt', skins: ['mole', 'frog', 'pop'] },
  { k: 'all', n: 'Weltraum', skins: ['planet', 'pop', 'mole'] },
  { k: 'stadion', n: 'Stadion', skins: ['goal', 'pop', 'fish'] },
  { k: 'insel', n: 'Schatzinsel', skins: ['chest', 'fish', 'goal'] },
  { k: 'kirmes', n: 'Jahrmarkt', skins: ['pop', 'goal', 'planet'] },
];
const SKINMAX = { planet: 13, mole: 15, fish: 18, goal: 16, chest: 34 }; // Ballon und Frosch gibt es nur noch als neue Spiele
const SKINNAME = { pop: 'Ballon-Jagd', planet: 'Raketen-Flug', frog: 'Frosch-Hüpfer', mole: 'Maulwurf-Spiel', fish: 'Angeln', goal: 'Torschuss', chest: 'Schatzsuche', thumb: 'Daumen-Karte', flip: 'Memory', pairs: 'Kabel verbinden', train: 'Zug beladen', bubbles: 'Buchstaben-Blasen', sort: 'Fließband', order: 'Reihenfolge', safe: 'Tresor knacken', mc: 'Kniffel-Frage', sim: 'Echte Szene' };
const SKINIC = { pop: 'balloon', planet: 'star', frog: 'frog', mole: 'target', fish: 'drop', goal: 'target', chest: 'coin', thumb: 'check', flip: 'cards', pairs: 'cards', train: 'train', bubbles: 'bubble', sort: 'sort', order: 'sort', safe: 'lock', mc: 'bulb', sim: 'shield' };
function skinFor(x) {
  const k = x.k, W = LS.world, used = LS.used;
  if (k === 'sim') return 'sim';
  if (LS.custom && LS.custom.sim) return k === 'tf' ? 'thumb' : 'mc';
  if (x._quiz) return 'mc';
  if (k === 'tf') return 'thumb';
  if (k === 'pad') return 'safe';
  if (k === 'pairs') return x.p.length <= 6 && x.p.every((p) => p[0].length <= 22 && p[1].length <= 22) && (x.last || used.flip === undefined) ? 'flip' : 'pairs';
  if (k === 'build') return 'train';
  if (k === 'spell') return 'bubbles';
  if (k === 'order') return 'order';
  if (k === 'sort') return 'sort';
  const o = [x.a, ...x.w], len = Math.max(...o.map((t) => String(t).length));
  let c = Object.keys(SKINMAX).filter((s) => SKINMAX[s] >= len && !(k === 'listen' && s === 'pop') && !(s === 'chest' && innerWidth < 560 && len > 14) && !(s === 'fish' && innerWidth < 560 && len > 9));
  if (!x._re) { const fresh = c.filter((s) => !used[s]); c = fresh; } // kein Spiel doppelt pro Lektion
  if (!c.length) return 'mc';
  c.sort((a, b) => (used[a] || 0) - (used[b] || 0) || (W.skins.indexOf(b) >= 0) - (W.skins.indexOf(a) >= 0) || Math.random() - .5);
  const best = c.filter((s) => s !== LS.lastSkin);
  return (best.length ? best : c)[0];
}

/* Kopfzeile über dem Spiel: Lückensatz, Bild oder Hören */
function preHTML(x) {
  if (x.k === 'gap') { const p = x.q.split('___'); return `<div class="gq">${glueGap(p[0], '<span class="gqg">?</span>', p.slice(1).join('___'))}</div>`; }
  if (x.k === 'listen') return `<div class="gq lsq"><button class="lspk" aria-label="Anhören">${I('snd')}</button><button class="lspk slow" aria-label="Langsam anhören">${I('snd')}<small>langsam</small></button></div>`;
  if (x.art && ART[x.art]) return `<div class="gq gqa">${ART[x.art]}</div>`;
  return '';
}
function listenHook(x, h, ctx) {
  const say = (slow) => { stopVoice(); const b = $$('.lspk', h)[slow ? 1 : 0]; if (!b || !b.isConnected) return; restart(b, 'xplay'); const url = CLIPS[SUBJ[st.s].tutor.id + '|' + x.vs]; if (url) { curAudio = freshAudio(url); if (slow) curAudio.playbackRate = .72; curAudio.play().catch(() => {}); return; } if (typeof noSoundView === 'function') noSoundView(x, h); };
  $$('.lspk', h).forEach((b, i) => (b.onclick = () => say(i === 1)));
  setTimeout(() => { if (alive(ctx.T) && !(typeof NOSND !== 'undefined' && NOSND)) say(false); }, 450);
}
/* Belohnung: Münzen, Edelsteine und Sterne fliegen heraus */
