  const amb = (src, n, cls) => [...Array(n)].map((_, i) => `<img class="gamb ${cls}" src="${src}" alt="" style="--i:${i};--x:${(12 + i * 83 / n + rnd(-5, 5)).toFixed(0)}%;--dl:-${rnd(0, 8).toFixed(1)}s">`).join('');
  // Angeln
