  SK.fish.item = (t, i, n) => `<button class="fsh nf${i % 2 ? ' fl' : ''}" data-v="${i}" style="--fx:${i % 2 ? 50 : 5}%;--y:${24 + i * (60 / Math.max(1, n - 1))}%;--dl:-${rnd(0, 3).toFixed(1)}s"><img class="fim" src="${P('fish', 'f' + (i % 4))}" alt=""><span>${t}</span></button>`;
  const fw = SK.fish.win; SK.fish.win = (el, sc) => { fw(el, sc); setTimeout(() => fxAt(sc, el, P('fish', 'splash'), 'gsplash'), 380); };
  const ff = SK.fish.fail; SK.fish.fail = (el, sc) => { ff(el, sc); fxAt(sc, el, P('fish', 'bubbles'), 'gpuff'); };
  // Maulwurf
  SK.mole.scene = `<img class="gbg" src="${P('mole', 'bg2')}" alt=""><img class="ghammer" src="${P('mole', 'hammer')}" alt="">`;
  SK.mole.item = (t, i, n) => `<div class="mh nm" style="--dl:${(i * .55).toFixed(2)}s"><img class="mhole" src="${P('mole', 'hole')}" alt=""><button class="ml" data-v="${i}"><img class="mim" src="${P('mole', 'sign')}" alt=""><span>${t}</span></button></div>`;
  const mw = SK.mole.win; SK.mole.win = (el, sc) => { const im = $('.mim', el); if (im) im.src = P('mole', 'happy'); el.classList.add('nosign'); const hm = $('.ghammer', sc); if (hm) { const r = el.getBoundingClientRect(), s = sc.getBoundingClientRect(); hm.style.left = r.left - s.left + r.width * .6 + 'px'; hm.style.top = r.top - s.top - 10 + 'px'; restart(hm, 'hit'); } fxAt(sc, el, P('mole', 'burst'), 'gburst'); mw(el, sc); };
  const mf = SK.mole.fail; SK.mole.fail = (el, sc) => { const im = $('.mim', el); if (im) im.src = P('mole', 'dizzy'); el.classList.add('nosign'); fxAt(sc, el, P('mole', 'dirt'), 'gdirt'); mf(el, sc); };
  // Torschuss
  SK.goal.scene = `<img class="gbg" src="${P('goal', 'bg')}" alt=""><img class="gkeep" src="${P('goal', 'keep')}" alt=""><div class="ball"><img src="${P('goal', 'ball')}" alt=""></div>`;
  SK.goal.item = (t, i, n) => `<button class="gl ng" data-v="${i}"><span class="gln"><img class="gim" src="${P('goal', 'goal')}" alt=""><span class="glb">${t}</span></span></button>`;
  const gw = SK.goal.win; SK.goal.win = (el, sc) => { gw(el, sc); setTimeout(() => { const im = $('.gim', el); if (im) im.src = P('goal', 'goaltor'); fxAt(sc, el, P('goal', 'confetti'), 'gconf', 1300); }, 600); };
  const gf = SK.goal.fail; SK.goal.fail = (el, sc) => { const k = $('.gkeep', sc); if (k) { const r = el.getBoundingClientRect(), s = sc.getBoundingClientRect(); k.src = P('goal', 'keepdive'); k.style.left = r.left - s.left + r.width / 2 + 'px'; k.classList.add('dive'); } gf(el, sc); };
  // Raketen-Flug
  SK.planet.scene = `<img class="gbg" src="${P('planet', 'bg')}" alt="">${amb(P('planet', 'star'), 5, 'gtw')}<img class="gastro" src="${P('planet', 'astro')}" alt=""><div class="rkt"><img class="rim" src="${P('planet', 'rocket')}" alt=""><img class="flame" src="${P('planet', 'flame')}" alt=""></div>`;
  SK.planet.item = (t, i, n) => `<button class="qpl np" data-v="${i}" style="--px:${(100 / (n + 1)) * (i + 1)}%;--py:${i % 2 ? 34 : 14}%;--dl:-${i * .9}s;--hue:${[0, 150, 260, 80, 200, 320][i % 6]}deg"><img class="pim" src="${P('planet', 'ring')}" alt=""><span>${t}</span></button>`;
  const pw = SK.planet.win; SK.planet.win = (el, sc) => { pw(el, sc); setTimeout(() => fxAt(sc, el, P('planet', 'star'), 'gburst'), 880); };
