  if (vv && !o._vv) { o._vv = 1; vv.addEventListener('resize', () => o._fit && o._fit()); vv.addEventListener('scroll', () => o._fit && o._fit()); addEventListener('resize', () => o._fit && o._fit()); }
  o._fit = fit; fit();
