  function hideHand() { hand.hidden = true; }
  const first = nextOpen(-1);
  const close = () => { cfClear(); o.classList.remove('on', 'kb'); o.style.top = ''; o.style.height = ''; document.body.classList.remove('wsopen'); stopVoice(); document.removeEventListener('keydown', esc0); if (O.onClose) O.onClose(); };
  const esc0 = (e) => { if (e.key === 'Escape' && o.classList.contains('on') && !$('.les.on')) close(); };
  document.addEventListener('keydown', esc0);
  $('.wsx', o).onclick = close;
