    gt.innerHTML = `<b>${I('lock')}Nur für Eltern</b><p>${usePw ? 'Bitte geben Sie Ihr Eltern-Passwort ein.' : `Bitte rechnen Sie: <b>${a} × ${m}</b>`}</p><div class="pfgr"><input id="pfgi" ${usePw ? 'type="password" autocomplete="current-password" placeholder="Eltern-Passwort"' : 'inputmode="numeric" placeholder="Ergebnis"'}><button class="b3d c" id="pfgo">Weiter zur Kündigung</button></div><p class="pyerr" id="pfge"></p>`;
    $('#pfgi').focus();
