let parOpen = false;
function pinPad(title, sub, onDone, extra = '', o = {}) {
  const h = $('#apar'); let v = '';
  h.innerHTML = `<div class="pgate${o.make ? ' make' : ''}">${o.step ? `<span class="pgstep">${o.step}</span>` : ''}<span class="pgi">${I('lock')}</span><b>${title}</b><p>${sub}</p><div class="pdots">${[0, 1, 2, 3].map(() => '<i></i>').join('')}</div>
    <div class="keys pkeys">${[1, 2, 3, 4, 5, 6, 7, 8, 9, 'x', 0, 'del'].map((k) => k === 'x' ? '<span></span>' : `<button class="key${k === 'del' ? ' del' : ''}" data-k="${k}">${k === 'del' ? I('arrow') : k}</button>`).join('')}</div>${o.btn ? `<button class="b3d c wide pgok" disabled>${o.btn}</button>` : ''}${extra}</div>`;
  const dots = $$('.pdots i', h), ok = $('.pgok', h);
  const paint = () => { dots.forEach((d, i) => { d.classList.toggle('on', i < v.length); d.textContent = o.make && i < v.length ? v[i] : ''; }); if (ok) ok.disabled = v.length < 4; };
  const fail = () => { v = ''; paint(); restart($('.pgate', h), 'shk'); sfx.no(); };
  const done = () => { const r = onDone(v); if (r === false) fail(); };
  const put = (k) => { if (k === 'del') v = v.slice(0, -1); else if (v.length < 4) v += k; paint(); sfx.tap(); if (v.length === 4 && !ok) setTimeout(done, 150); };
  $$('.pkeys .key', h).forEach((b) => (b.onclick = () => put(b.dataset.k)));
  if (ok) ok.onclick = () => { if (v.length === 4) done(); };
  return { fail };
}
