const kSoon = () => { if (!K.tok) return; clearTimeout(kTimer); kTimer = setTimeout(kPush, 2500); };
/* Jede Änderung an Lerndaten landet automatisch im Konto */
(() => { try { const o = Storage.prototype.setItem; Storage.prototype.setItem = function (k, v) { o.call(this, k, v); if (this === localStorage && typeof k === 'string' && k.startsWith('gsm-') && !KSKIP.includes(k)) kSoon(); }; } catch (e) {} })();
addEventListener('pagehide', () => { if (K.tok) { try { navigator.sendBeacon && navigator.sendBeacon(K_URL, new Blob([JSON.stringify({ mode: 'save', token: K.tok, data: kCollect() })], { type: 'text/plain' })); } catch (e) {} } });
