/* Level-Aufstieg und neue Traumberufe */
async function lobCheckLevel(prevL) {
  const lv = lobLevel(), seen = +lsx.get('gsm-llv', 0) || 0, from = Math.max(seen, prevL || 0);
  if (!seen) { lsx.set('gsm-llv', lv.L); if (lv.L <= 1) return; }
  if (lv.L <= from) { lsx.set('gsm-llv', Math.max(seen, lv.L)); return; }
  lsx.set('gsm-llv', lv.L); GT.t('Level erreicht', 'Level ' + lv.L);
  const nj = LJOBS.filter((j) => j[3] > from && j[3] <= lv.L), np = LPETS.filter((p) => p[2] > from && p[2] <= lv.L && p[2] > 1 && PET_OK.has(p[0]));
  ls('lvup', .9);
  const big = document.createElement('div'); big.className = 'loblv'; big.innerHTML = `<small>Level aufgestiegen</small><b>${lv.L}</b>`; $('#lobby').appendChild(big);
  setTimeout(() => confetti(90), 300);
  setTimeout(() => big.classList.add('out'), 2300); setTimeout(() => big.remove(), 2900);
  await new Promise((r0) => setTimeout(r0, 2900));
  if (nj.length) await lobReveal(nj[nj.length - 1]);
  if (np.length) await lobRevealPet(np[np.length - 1]);
}

function lobRevealPet(p) {
  const o = document.createElement('div'); o.className = 'lobov lobrev';
  o.innerHTML = `<div class="lobcard"><small class="lrk">Neues Haustier freigeschaltet</small><div class="lrf"><i class="lrsh"></i><img src="${LOBB}pets/${p[0]}-sit.webp?v=3" alt="" onerror="this.style.visibility='hidden'"></div><b class="lrt">${esc(p[1])}</b><p>Dein Haustier begleitet dich in jeder Welt.</p><button type="button" class="b3d lg lrgo">Mitnehmen</button><button type="button" class="lnk lrno">Später</button></div>`;
  $('#lobby').appendChild(o); requestAnimationFrame(() => o.classList.add('on')); ls('unlock', .9);
  return new Promise((done) => {
    const close = () => { o.classList.remove('on'); setTimeout(() => o.remove(), 300); };
    $('.lrgo', o).onclick = () => { close(); lsx.set('gsm-lpet', p[0]); lobDraw(); if (LOBE) LOBE.setPet(p[0]); setTimeout(done, 500); };
    $('.lrno', o).onclick = () => { ls('tap', .6); close(); done(); };
  });
}
let lobSeqOn = false;
