function patURL(k, dark) {
  let inner = '';
  if (k === 'sach') inner = '<g fill="none" stroke="#fff" stroke-width="3" opacity=".22"><path d="M20 70C18 40 40 20 72 18c2 34-20 54-52 52zM20 70l30-30"/><path d="M130 140c-2-26 18-44 46-46 2 30-18 48-46 46zM130 140l26-26"/><circle cx="150" cy="40" r="8"/><circle cx="40" cy="150" r="5"/></g>';
  else if (k === 'ki') inner = '<g fill="none" stroke="#fff" stroke-width="3" opacity=".22"><path d="M10 40h50v40h60V30h60M30 160v-40h70v40h70M150 10v50"/></g><g fill="#fff" opacity=".28"><circle cx="60" cy="40" r="6"/><circle cx="120" cy="80" r="6"/><circle cx="100" cy="120" r="6"/><circle cx="150" cy="60" r="6"/></g>';
  else PAT[k].forEach((t, i) => { inner += `<text x="${[20, 120, 70, 160, 30, 110][i]}" y="${[40, 30, 100, 120, 170, 175][i]}" font-family="Arial Black,Arial,sans-serif" font-weight="900" font-size="${t.length > 2 ? 26 : 38}" fill="#fff" opacity=".2" transform="rotate(${[-12, 10, -6, 14, 8, -10][i]} ${[20, 120, 70, 160, 30, 110][i]} ${[40, 30, 100, 120, 170, 175][i]})">${t}</text>`; });
  if (dark) inner = inner.replace(/#fff/g, '#1d2a4a').replace(/opacity="\.(\d+)"/g, (m, d) => `opacity="${(+('.' + d) * .45).toFixed(3)}"`);
  return `url("data:image/svg+xml,${encodeURIComponent(`<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'>${inner.replace(/"/g, "'")}</svg>`)}")`;
}
