function gQuiz(T) {
  gs.className = 'gs g-quiz';
  const S = SUBJ[st.s], L = QZ[S.k][G()]; let i = 0, tries = 0;
  function show() {
    const x = L[i]; tries = 0;
    gs.innerHTML = `<div class="qq"><small>Aufgabe ${i + 1} von ${L.length}</small>${x.q}</div>${x.viz ? `<div class="viz">${x.viz}</div>` : ''}<div class="qo">${x.o.map((o, k) => `<button class="b3d q${k}" data-k="${k}">${o}</button>`).join('')}</div>`;
    $$('.qo button', gs).forEach((b) => (b.onclick = () => choose(b, +b.dataset.k)));
    if (i) voice(x.qk);
  }
  function choose(b, k) {
    const x = L[i];
    if (k === x.a) {
      b.classList.add('ok'); sfx.ok(); if (tries === 0) right(); else { st.done++; drawProg(); }
      $$('.qo button', gs).forEach((y) => (y.disabled = true));
      dmax.className = 'dmax happy'; sayEl.textContent = 'Richtig!'; voice(x.ek);
      fb(true, 'Richtig!', x.e, { btn: i < L.length - 1 ? 'Weiter' : 'Fertig', on: () => { i++; if (i < L.length) show(); else finish('Üben geschafft!', 'Im Abo gibt es zu jedem Thema solche Übungen, und vor der Klassenarbeit einen Probetest.'); } });
    } else {
      tries++; wrong(); b.classList.add('no'); b.disabled = true; sfx.no(); restart(b, 'shk');
      say('Fast! Schau nochmal genau hin.', 'think', P.no[1]);
    }
  }
  progress(L.length); show(); sayK(vkQI);
  return () => {};
}

